import java.util.*;
import java.lang.*;
import java.io.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            String s = sc.next();
            int n = s.length();
            int[] count = new int[26];
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                count[c - 'a']++;
            }
            boolean flag = false;
            for (int i = 0; i < 26; i++) {
                if (count[i] % 2 == 1) {
                    flag = true;
                    break;
                }
            }
            if (flag)
                System.out.println("mutter about something");
            else
                System.out.println("mutter");
        }
    }
}

